insert into claims (id, team_id, case_id, text, logic_line, ord, citation_ids, created_at, created_by, updated_at) values
  ('016342ef-9507-425e-b013-79c440a1a8fc', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'Even a more accurate AI would not remove the core objection: decisions to kill need meaningful human judgment and a responsible human.', 'Because autonomous killing creates a responsibility gap (S1), humans "in the loop" drift into rubber-stamping (S2), and greater distance makes war easier to start (S3), accuracy alone cannot justify removing human judgment.', 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z'),
  ('b239d8fc-64e8-4ba9-aa93-b9c6fcec29ac', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'A company may refuse uses it judges unethical, but the binding limits on lethal autonomy and domestic mass surveillance belong in public law.', 'Because makers share responsibility for foreseeable uses of what they build (S1), democratic governments, not vendors, must set national policy (S2), and mass surveillance threatens the democratic accountability the military itself relies on (S3), the right answer is public, legal guardrails rather than private vetoes.', 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z'),
  ('d4d11d10-23d6-4307-bae4-091c8fc237e4', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'San Francisco was justified in keeping the memorial, and diplomatic pressure is not a valid reason to remove it.', 'Because San Francisco has a real connection to this history (S1), memorials serve justice for victims whose suffering hasn''t been adequately acknowledged (S2), and the statue honors victims rather than accusing today''s Japanese people (S3), keeping it was justified.', 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z'),
  ('2b8fd8f4-0bfc-4271-bf2a-45ab4847982b', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'The right standard for public memory has four tests, and it binds the U.S. as much as Japan.', 'Because a principle we apply to others must apply to ourselves (S1), societies that confront their own wrongs show it can be done well (S2), and the community most connected to a history should decide, with victims at the center (S3), the U.S. must hold its own monuments to the same four tests.', 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z'),
  ('00913420-8750-4ff3-a5c9-1a664aa09787', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'We have no moral duty to be beautiful.', 'Because duties attach to what we control and what we owe others (S1), treating beauty as a moral standard punishes people for traits they didn''t choose (S2), and a benefit to the individual is not an obligation (S3), there is no duty to be beautiful.', 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z'),
  ('b9834a6a-ddcc-4ec1-aca6-0aba625e0eda', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'Caring for one''s appearance is a permissible choice, but marketing extreme practices to young people and profiting from insecurity is wrong.', 'Because autonomous adults may shape their own bodies (S1), minors and insecure audiences can''t consent freely to a market built on their anxieties (S2), and each person''s maxxing raises the bar for everyone (S3), the practice is permissible as personal choice but its predatory promotion is not.', 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z'),
  ('801067f8-89a5-4288-82fa-add18c826dcb', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'Markets on war, death and the removal of leaders are morally wrong.', 'Because these markets reward secret knowledge that insiders control (S1), they put a price on human lives and suffering (S2), and they can create incentives to cause or time the events themselves (S3), they should not exist.', 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z'),
  ('33f8280b-88c9-46ee-962b-36ab06e7fe50', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'Markets on public, scheduled events can be permissible, with safeguards for fairness and gambling harm.', 'Because elections and economic data are public processes no single insider controls (S1), adults may risk their own money on their own judgment (S2), and strong safeguards can address insider trading and addiction (S3), these markets can be permissible.', 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z'),
  ('8869f469-b83b-411f-b5fb-0c5f3f482c9d', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'Accessibility lawsuits, including serial ones, are justified civil-rights enforcement.', 'Because inaccessibility is a real wrong of exclusion (S1), the law deliberately recruited private enforcers (S2), and disability rights has always advanced through friction (S3), suing businesses that keep barriers is justified.', 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z'),
  ('3256e0ed-fe44-4d99-9592-958214cb95bf', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 'The per-visit bounty pays for findings, not fixes, so enforcement should be redesigned around repair and scaled to knowledge, control and capacity.', 'Because a bounty rewards the violations cheapest to prove against the defendants least able to fight (S1), it can produce closures instead of ramps (S2), and responsibility for an inherited environment is shared and follows control (S3), the remedy should pay for repair and fall hardest on those with power.', 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z'),
  ('81252dd4-6c94-451c-be9b-f49d66562a94', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'The British Museum''s title is defective, and the duty to repair falls on the institution that still benefits.', 'Because the Stone changed hands as a spoil of war between empires (S1), keeping taken objects for being "the better caretaker" can''t be a universal rule (S2), and responsibility for an inherited wrong follows power and benefit (S3), the museum carries the duty to return it.', 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z'),
  ('ffc6e77e-8e02-4ae6-8024-0b859b54a057', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'The classic reasons for keeping the Stone no longer hold, and return should come with a reciprocal partnership now.', 'Because the GEM ties London on care and wins on connection (S1), the law already bends when the moral case is accepted (S2), and an early, structured return protects the public and serves both sides (S3), the Stone should go now with a partnership.', 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z'),
  ('f3cc4ca5-351e-42d6-bdf9-c91ca4c46ff0', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 10), 'De-indexing records of acquittals and minor, old offenses is permissible, and often required.', 'Because an acquittal means the state failed to prove guilt (S1), permanent searchability punishes people beyond any sentence (S2), and de-indexing keeps the record while restoring "practical obscurity" (S3), the Delhi court''s approach is justified.', 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z'),
  ('5855770f-a82b-4bc4-9e9e-829a3ef53f84', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 10), 'The right depends on the kind of information: consent and public power decide the tier.', 'Because information posted without consent was never fairly public (S1), people seeking public power invite scrutiny of their own words (S2), and government and press records serve accountability (S3), the right must be tiered.', 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z'),
  ('51a62b6c-b1d6-408d-8112-2440574a4049', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'Tainted money can be accepted when it wasn''t produced by the wrong, because refusing it costs lives and repairs nothing.', 'Because the HPV program saves lives that refusal would cost (S1), money''s moral status depends on how it was made more than who holds it (S2), and refusing doesn''t help the wronged (S3), partners may continue, with conditions.', 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z'),
  ('00dacd7c-b346-45cf-980e-e95922499d09', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 'Nonprofits must refuse money that launders reputation or destroys the trust their mission depends on.', 'Because charity can be used to buy moral cover (S1), public health programs depend on community trust (S2), and accepting money is a public act that sends a message (S3), organizations must protect their independence and sometimes refuse.', 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z'),
  ('95637825-2265-4fcd-a91d-324f2bbc976a', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'Some health speech may be regulated: checkable, false claims presented as expertise or used to sell, which risk serious physical harm.', 'Because the state may limit speech to prevent serious harm to others (S1), some health claims clearly cause such harm (S2), and borrowing medical authority creates duties ordinary conversation doesn''t have (S3), narrow regulation of those claims is justified.', 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z'),
  ('a0a16644-fce4-4afd-9c37-d4c49194f3f2', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 'Credential labels and corrections are justified; licensing all health talk is not, and Article 4''s values test never is.', 'Because medical knowledge is fallible and often corrected by outsiders (S1), whoever decides what is false must not have a stake in the answer (S2), and labels inform without silencing (S3), the right tool is labels and corrections by an independent body.', 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z'),
  ('f6aa0380-a00e-4dd8-a806-f1fe26b32d6a', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'Speakers of dehumanizing rhetoric share moral responsibility for violence it inspires.', 'Because you can be responsible for harm that passes through someone else''s free choice when you knowingly raise its risk (S1), a tiny chance times a huge audience is a serious risk (S2), and dehumanizing rhetoric is morally different from harsh opinion (S3), these speakers share responsibility.', 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z'),
  ('1bc9700f-85d0-4222-876c-66b4c7a072e1', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 'Responsibility scales with content, reach, foreseeability and persistence, but legal liability should stay at incitement to imminent violence.', 'Because speakers can prevent misuse and choose their words (S1), foreseeability grows once violence has followed (S2), and the power to punish "dangerous rhetoric" is itself dangerous (S3), moral responsibility scales while legal liability stays narrow.', 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z'),
  ('0b80ab94-259a-4981-a35c-0f1002ef9d19', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'AI companion companies bear moral responsibility for foreseeable harms their design makes more likely.', 'Because the technology is not neutral (S1), interactive companions differ from static media (S2), and the risk to vulnerable users was foreseeable (S3), companies share responsibility.', 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z'),
  ('26df9148-01f1-4510-a4e1-587db7449792', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 'The minimum duty is to recognize crisis signals, break character and connect users to human help; heavier limits should be proportionate.', 'Because the "what" of a product determines which guardrails it needs (S1), the safeguards are feasible and cheap compared with the harm (S2), and over-restriction has costs too (S3), the right duty is a firm minimum with proportionate additions.', 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z'),
  ('8430410c-72b9-401e-b688-6eafea5921c0', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'Sentient animals have moral worth, so treating them as mere property is wrong.', 'Because the capacity to suffer is what makes suffering matter morally (S1), science and law increasingly recognize animal sentience (S2), and property law ignores that difference (S3), mere property status is wrong.', 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z'),
  ('41b2b627-99d3-4771-81d6-28070747ae78', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 'Harm to animals is permissible only when necessary and minimized, which condemns factory farming but doesn''t require full personhood.', 'Because "ought implies can" and human needs are real (S1), legal standing can protect beings who can''t speak for themselves (S2), and factory farming fails the necessity test (S3), we support protection from unjustified harm, not full personhood.', 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z')
insert into supports (id, claim_id, team_id, case_id, text, logic_line, ord, citation_ids, created_at, created_by, updated_at) values
  ('c90b7acd-9fa2-4a9e-a7cf-9f13c8983668', '016342ef-9507-425e-b013-79c440a1a8fc', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'The responsibility gap When a machine selects and engages a target, no one may be fully answerable: not the programmer, the commander, or the machine.', null, 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z'),
  ('cb170cb3-80e8-4fe2-a231-505433dac4ac', '016342ef-9507-425e-b013-79c440a1a8fc', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'Automation bias People formally "in the loop" come to defer to the system''s recommendation.', null, 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z'),
  ('c74f74b5-ae6c-4869-919d-de3f5134870b', '016342ef-9507-425e-b013-79c440a1a8fc', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'Distance lowers the threshold for war Each step that removes risk from the side using force makes force easier to choose.', null, 2, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z'),
  ('c8e824ca-cfb7-4d34-bc35-08f1e5dfe1a0', 'b239d8fc-64e8-4ba9-aa93-b9c6fcec29ac', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'Makers can be complicit in foreseeable uses A company that knowingly supplies a tool for a use it believes is wrong shares responsibility for that use.', null, 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z'),
  ('2b42f81c-ee47-4288-b6ed-ac0344cb2d7a', 'b239d8fc-64e8-4ba9-aa93-b9c6fcec29ac', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'Democratic legitimacy cuts the other way too Unelected companies shouldn''t set military policy for a democracy, as the Pentagon argues in the case. That means the durable fix is law.', null, 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z'),
  ('6091c1be-9f2c-43b8-bd91-6592c3b61d72', 'b239d8fc-64e8-4ba9-aa93-b9c6fcec29ac', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 'Mass surveillance of citizens undermines democracy itself People who know they are always watched speak and organize less freely.', null, 2, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333301', '2026-11-01T00:00:00.000Z'),
  ('f173a0e4-0d0b-46a3-af33-47378d524e78', 'd4d11d10-23d6-4307-bae4-091c8fc237e4', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'Real connection San Francisco has large Chinese and Korean communities, and the U.S. military reportedly took part in the abuse, so the U.S. shares some accountability.', null, 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z'),
  ('b4180bf8-9ffc-47c1-ad4c-bc5de0cee3ac', 'd4d11d10-23d6-4307-bae4-091c8fc237e4', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'Memory is a form of justice owed to victims When wrongs go unacknowledged, public memory is one of the few remedies left.', null, 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z'),
  ('cc83ce18-3f0b-4961-a055-16ff00c6cb21', 'd4d11d10-23d6-4307-bae4-091c8fc237e4', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'Remembrance is not accusation The statue honors "all other women affected by such crimes," not only victims of Japan.', null, 2, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z'),
  ('d415339b-79f1-4147-883d-132a5634c255', '2b8fd8f4-0bfc-4271-bf2a-45ab4847982b', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'Consistency Memorializing another country''s wrongs while honoring our own perpetrators is a double standard.', null, 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z'),
  ('578bf4c8-30f7-4eb3-8af8-c4736b3bd6c7', '2b8fd8f4-0bfc-4271-bf2a-45ab4847982b', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'Acknowledgment works Countries can face their own atrocities without collapse.', null, 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z'),
  ('46d55722-da54-423c-9aa9-4c2e07cf32a8', '2b8fd8f4-0bfc-4271-bf2a-45ab4847982b', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 'Local communities decide, with victims at the center', null, 2, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333302', '2026-11-01T00:00:00.000Z'),
  ('80b51817-2be7-4994-9bde-9162549cae9d', '00913420-8750-4ff3-a5c9-1a664aa09787', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'Duties track control and what we owe others "Ought implies can": morality can''t require what people can''t do, and much of appearance comes from genetics, illness or disability.', null, 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z'),
  ('528840d3-6476-4d2f-97ee-79291a4394dc', '00913420-8750-4ff3-a5c9-1a664aa09787', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'Making beauty a moral ideal produces unjust judgments', null, 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z'),
  ('22d882f5-5c06-42d5-a543-4cb7751940ba', '00913420-8750-4ff3-a5c9-1a664aa09787', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'Benefit is not duty That something pays off doesn''t mean we owe it to anyone.', null, 2, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z'),
  ('9b5f6adc-bfe7-4cb1-94c1-c03085d2a233', 'b9834a6a-ddcc-4ec1-aca6-0aba625e0eda', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'Autonomy covers self-care Grooming, fitness and even elective procedures can express a person''s own goals.', null, 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z'),
  ('24b6b2a2-55ab-4369-8c0e-08d79907034f', 'b9834a6a-ddcc-4ec1-aca6-0aba625e0eda', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'Consent requires freedom from manipulation and enough maturity The movement mainly targets adolescents.', null, 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z'),
  ('ecf7a90f-765e-4415-a433-daa00054eef3', 'b9834a6a-ddcc-4ec1-aca6-0aba625e0eda', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 'Looks work like an arms race When everyone invests to look better than others, the standard rises and no one gains relative advantage, but everyone pays.', null, 2, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333303', '2026-11-01T00:00:00.000Z'),
  ('830a7389-5426-480c-97e0-917bdbca2875', '801067f8-89a5-4288-82fa-add18c826dcb', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'Inside knowledge decides these outcomes When the event is a secret operation, the only people who can "forecast" well are the people planning it.', null, 0, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z'),
  ('84c87654-fe66-45c7-8b07-2c75ed6f691c', '801067f8-89a5-4288-82fa-add18c826dcb', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'Lives become commodities Betting on a person''s death or a war treats the people affected as mere instruments for profit.', null, 1, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z'),
  ('24125672-f441-47f8-ab7f-a2ec60576872', '801067f8-89a5-4288-82fa-add18c826dcb', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 'Incentives can bend the event When someone profits from an outcome they can influence, they have a reason to make it happen or time it.', null, 2, '{}'::uuid[], '2026-11-01T00:00:00.000Z', 'a3333333-3333-3333-3333-333333333304', '2026-11-01T00:00:00.000Z'),
